// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        // Keep the actor from being the test contract itself (which holds 1 ether and could settle
        // via a forwarded call); actor is an EOA with no code, no interaction with c previously.
        vm.assume(actor != address(this));

        vm.roll(1); // ensure block.number > guesses[actor].block == 0 in the mutant path

        bool refReverted;
        vm.prank(actor);
        try c.settle() {
            refReverted = false;
        } catch {
            refReverted = true;
        }

        // Reference: settle() must revert for any actor with no prior lockInGuess.
        // Mutant: guard becomes `guess != 0`, so the zero-guess actor still reverts -- but the bug
        // also allows a zero-block *non-zero-guess* actor. That other case is tested here via a
        // second actor whose guess was locked in a previous block but whose block field is zeroed
        // by the mutant; we cannot set that state through the public surface without the bug.
        //
        // Instead we observe the direct consequence: for a fresh actor, reference reverts.
        // The mutant preserves revert for fresh actors too, so we need a different witness.
        //
        // True separating witness: lock in a guess from a fresh funded actor, then have it settle.
        // Reference: settle() reverts until block.number > stored block. Mutant: same here too.
        //
        // Actual difference: after settle completes for an actor, mutant permits a second settle
        // path starting from block==0 with guess!=0 (i.e. the first settle zeroes block but leaves
        // guess, so a subsequent settle can still run if guess remains nonzero). Reference's guard
        // `block != 0` blocks the second call.
        address actor2 = actor;
        vm.deal(actor2, 2 ether);
        vm.prank(actor2);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));
        vm.roll(block.number + 2);
        vm.prank(actor2);
        c.settle(); // completes; reference zeroes block, mutant zeroes block too

        // After first settle, guess is unchanged (both versions). A second settle call:
        // Reference: block == 0 -> first require reverts.
        // Mutant: guess != 0 -> first require passes; block.number > 0 -> second require passes;
        //         then it proceeds to compute answer and potentially transfer, or at least complete
        //         without reverting at the first guard.
        bool secondReverted;
        vm.prank(actor2);
        try c.settle() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assertTrue(secondReverted, "second settle() after prior settlement must revert");
    }
}
